"""Generate docs/taxonomy.md from the YAML. Never hand-edit the Markdown.

The generated page leads with the verification count rather than burying it, because a
reader's first question about a table of legal citations is how many of them were actually
checked.
"""

from __future__ import annotations

import datetime as dt
from pathlib import Path

from sever.taxonomy.loader import Decision, Provision, Statute, Taxonomy, load_taxonomy

DOCS_TAXONOMY = Path(__file__).resolve().parents[2] / "docs" / "taxonomy.md"

_BANNER = (
    "<!-- Generated by `sever taxonomy render` from sever/taxonomy/*.yaml. "
    "Do not hand-edit: your changes will be overwritten. -->"
)


def _para(text: str) -> str:
    """YAML folded scalars arrive with a trailing newline and internal single newlines."""
    return " ".join(text.split())


def _provision_row(p: Provision, statutes: dict[str, Statute]) -> str:
    statute = statutes[p.statute]
    cite = f"{statute.title}, {p.citation}"
    if p.is_verified:
        assert p.quote is not None and p.checked_on is not None
        mark = f"checked {p.checked_on.isoformat()}"
        detail = f'"{_para(p.quote)}"'
    else:
        assert p.unverified is not None
        mark = "**not checked**"
        detail = _para(p.unverified)
    return f"| {cite} | {p.heading} | {mark} | {detail} |"


def _decision_label(t: Taxonomy, d: Decision) -> str:
    return t.categories.decisions[d.value].label


def last_updated(t: Taxonomy) -> dt.date:
    """The most recent `updated:` date across the YAML files.

    The generated page is stamped with this rather than with today's date so that
    rendering is a pure function of the YAML: CI re-renders the page and fails on any
    diff, and a stamp that changed every day would fail that check on every day but one.
    """
    dates = [t.categories.updated, *(j.updated for j in t.jurisdictions.values())]
    return max(dates)


def render(t: Taxonomy, *, generated_on: dt.date | None = None) -> str:
    on = generated_on or last_updated(t)
    lines: list[str] = [_BANNER, "", "# The exemption taxonomy", ""]

    lines += [
        "Every redaction this tool proposes carries one of the codes below, and every code",
        "is tied to a provision of a real statute. The codes are the closed set: the",
        "decision layer cannot invent a category, and a span it cannot place lands on an",
        "escalation code rather than on a guess.",
        "",
        "**This is not legal advice and not a legal determination.** The mapping is a",
        "proposal a reviewer applies. A public body brings its own interpretation, and the",
        "mapping is a YAML file precisely so that it can.",
        "",
        f"Generated {on.isoformat()} from `sever/taxonomy/`, the date of its last update.",
        "",
    ]

    lines += ["## How much of this has been checked", ""]
    lines += [
        "A section number written from memory and a section number read off the",
        "consolidated text look identical in a table. They are not the same thing, so the",
        "taxonomy format refuses a provision that is neither verified nor explicitly",
        "marked unverified with a reason, and the counts are printed here.",
        "",
        "| Jurisdiction | Provisions verified against the consolidated text |",
        "|---|---|",
    ]
    for key, (ok, total) in sorted(t.verification_summary().items()):
        j = t.jurisdictions[key]
        pct = f"{ok / total:.0%}" if total else "n/a"
        lines.append(f"| {j.name} | {ok} of {total} ({pct}) |")
    lines += [
        "",
        "Unchecked rows are listed in full in the jurisdiction sections below, each with",
        "the reason it has not been checked. Nothing defaults to verified.",
        "",
    ]

    lines += ["## The codes", "", "| Code | Decision | Category |", "|---|---|---|"]
    for c in t.categories:
        lines.append(f"| `{c.code}` | {_decision_label(t, c.decision)} | {c.name} |")
    lines.append("")
    lines += [
        "Escalation withholds. An undecided span is proposed for redaction and flagged for",
        "the reviewer, never released on the assumption that it was probably fine.",
        "",
    ]

    lines += ["## What each code means", ""]
    for c in t.categories:
        lines += [f"### `{c.code}`: {c.name}", "", f"**{_decision_label(t, c.decision)}.** "
                  f"{_para(c.definition)}", ""]
        if c.reviewer_question:
            lines += [f"*The question behind it:* {_para(c.reviewer_question)}", ""]
        if c.examples:
            lines += ["Examples:", ""]
            lines += [f"- {_para(e)}" for e in c.examples]
            lines.append("")
        if c.traps:
            lines += ["Traps:", ""]
            lines += [f"- {_para(x)}" for x in c.traps]
            lines.append("")
        for key in sorted(t.jurisdictions):
            j = t.jurisdictions[key]
            if c.code in j.unmapped:
                lines += [f"*{j.name}:* not mapped. {_para(j.unmapped[c.code])}", ""]
                continue
            provisions = t.provisions(c.code, key)
            note = j.mappings[c.code].note
            if not provisions:
                text = _para(note) if note else "No provision cited."
                lines += [f"*{j.name}:* {text}", ""]
                continue
            lines += [f"*{j.name}:*", "", "| Provision | Heading | Verification | Text or reason |",
                      "|---|---|---|---|"]
            lines += [_provision_row(p, dict(j.statutes)) for p in provisions]
            lines.append("")
            if note:
                lines += [f"> {_para(note)}", ""]

    overridden = {k: t.overrides(k) for k in sorted(t.jurisdictions)}
    if any(overridden.values()):
        lines += [
            "## Where a jurisdiction decides a code differently",
            "",
            "A code means the same question everywhere, but the statutes do not always",
            "answer it the same way. Where they differ the jurisdiction says so here and",
            "the tool behaves accordingly: this is not documentation of an intention, it",
            "is the decision the pipeline applies for a span under that statute.",
            "",
            "Every published number in this repository is the federal configuration, which",
            "overrides nothing, so no result table is affected by the rows below.",
            "",
            "| Jurisdiction | Code | Default | Under this statute | Why |",
            "|---|---|---|---|---|",
        ]
        for key in sorted(overridden):
            for code, (decision, reason) in overridden[key].items():
                lines.append(
                    f"| {t.jurisdictions[key].name} | `{code}` | "
                    f"{t.categories[code].decision.value} | **{decision.value}** | "
                    f"{_para(reason)} |"
                )
        lines.append("")

    lines += ["## The statutes", ""]
    for key in sorted(t.jurisdictions):
        j = t.jurisdictions[key]
        lines += [f"**{j.name}**", ""]
        for s in j.statutes.values():
            consolidated = (
                s.consolidated_to.isoformat()
                if isinstance(s.consolidated_to, dt.date)
                else s.consolidated_to
            )
            lines.append(f"- [{s.title}]({s.url}) ({s.citation}); consolidation read: {consolidated}")
        lines.append("")

    lines += [
        "## Adding a jurisdiction",
        "",
        "Drop another YAML file into `sever/taxonomy/` beside `federal.yaml`. It declares",
        "its statutes, then answers every code in `categories.yaml`: either with the",
        "provisions that carry it, or by naming it in `unmapped` with the reason the Act",
        "has no equivalent. The loader refuses a file that leaves a code unanswered, and",
        "refuses a provision that claims nothing about whether it was checked.",
        "",
        "Where the new Act answers a code differently from `categories.yaml`, set",
        "`decision` on that code's mapping and say why in `decision_reason`. The loader",
        "refuses an override with no reason, because the override changes what is released",
        "and the reason is what a reviewer reads. Expect to need it rarely: a code whose",
        "decision changes between jurisdictions is usually two codes wearing one name.",
        "",
    ]
    return "\n".join(lines).rstrip() + "\n"


def write(path: Path = DOCS_TAXONOMY, taxonomy: Taxonomy | None = None) -> Path:
    t = taxonomy or load_taxonomy()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(render(t), encoding="utf-8")
    return path


if __name__ == "__main__":  # pragma: no cover
    print(write())
